macro_rules! AtomicWaker {
    () => {
        # [doc = " A synchronization primitive for task wakeup."] # [doc = ""] # [doc = " Sometimes the task interested in a given event will change over time."] # [doc = " An `AtomicWaker` can coordinate concurrent notifications with the consumer"] # [doc = " potentially \"updating\" the underlying task to wake up. This is useful in"] # [doc = " scenarios where a computation completes in another thread and wants to"] # [doc = " notify the consumer, but the consumer is in the process of being migrated to"] # [doc = " a new logical task."] # [doc = ""] # [doc = " Consumers should call `register` before checking the result of a computation"] # [doc = " and producers should call `wake` after producing the computation (this"] # [doc = " differs from the usual `thread::park` pattern). It is also permitted for"] # [doc = " `wake` to be called **before** `register`. This results in a no-op."] # [doc = ""] # [doc = " A single `AtomicWaker` may be reused for any number of calls to `register` or"] # [doc = " `wake`."] # [doc = ""] # [doc = " # Memory ordering"] # [doc = ""] # [doc = " Calling `register` \"acquires\" all memory \"released\" by calls to `wake`"] # [doc = " before the call to `register`.  Later calls to `wake` will wake the"] # [doc = " registered waker (on contention this wake might be triggered in `register`)."] # [doc = ""] # [doc = " For concurrent calls to `register` (should be avoided) the ordering is only"] # [doc = " guaranteed for the winning call."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Here is a simple example providing a `Flag` that can be signalled manually"] # [doc = " when it is ready."] # [doc = ""] # [doc = " ```"] # [doc = " use futures::future::Future;"] # [doc = " use futures::task::{Context, Poll, AtomicWaker};"] # [doc = " use std::sync::Arc;"] # [doc = " use std::sync::atomic::AtomicBool;"] # [doc = " use std::sync::atomic::Ordering::Relaxed;"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " struct Inner {"] # [doc = "     waker: AtomicWaker,"] # [doc = "     set: AtomicBool,"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(Clone)]"] # [doc = " struct Flag(Arc<Inner>);"] # [doc = ""] # [doc = " impl Flag {"] # [doc = "     pub fn new() -> Self {"] # [doc = "         Self(Arc::new(Inner {"] # [doc = "             waker: AtomicWaker::new(),"] # [doc = "             set: AtomicBool::new(false),"] # [doc = "         }))"] # [doc = "     }"] # [doc = ""] # [doc = "     pub fn signal(&self) {"] # [doc = "         self.0.set.store(true, Relaxed);"] # [doc = "         self.0.waker.wake();"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " impl Future for Flag {"] # [doc = "     type Output = ();"] # [doc = ""] # [doc = "     fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {"] # [doc = "         // quick check to avoid registration if already done."] # [doc = "         if self.0.set.load(Relaxed) {"] # [doc = "             return Poll::Ready(());"] # [doc = "         }"] # [doc = ""] # [doc = "         self.0.waker.register(cx.waker());"] # [doc = ""] # [doc = "         // Need to check condition **after** `register` to avoid a race"] # [doc = "         // condition that would result in lost notifications."] # [doc = "         if self.0.set.load(Relaxed) {"] # [doc = "             Poll::Ready(())"] # [doc = "         } else {"] # [doc = "             Poll::Pending"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] pub struct AtomicWaker { state : AtomicUsize , waker : UnsafeCell < Option < Waker > > , }
    };
}

AtomicWaker!();